CREATE TYPE "MissionStatus" AS ENUM ('DRAFT', 'PLANNING', 'RUNNING', 'WAITING_APPROVAL', 'PAUSED', 'COMPLETED', 'FAILED', 'CANCELLED');
CREATE TYPE "StepStatus" AS ENUM ('PENDING', 'RUNNING', 'WAITING_APPROVAL', 'SUCCEEDED', 'FAILED', 'SKIPPED');
CREATE TYPE "ApprovalStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED');
CREATE TYPE "RiskLevel" AS ENUM ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL');
CREATE TABLE "Mission" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "goal" TEXT NOT NULL, "status" "MissionStatus" NOT NULL DEFAULT 'DRAFT', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Mission_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AgentStep" ("id" TEXT NOT NULL, "missionId" TEXT NOT NULL, "order" INTEGER NOT NULL, "objective" TEXT NOT NULL, "action" TEXT NOT NULL, "tool" TEXT NOT NULL, "target" TEXT, "status" "StepStatus" NOT NULL DEFAULT 'PENDING', "reasoningSummary" TEXT, "expectedOutcome" TEXT, "actualOutcome" TEXT, "confidence" DOUBLE PRECISION, "startedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), CONSTRAINT "AgentStep_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Evidence" ("id" TEXT NOT NULL, "stepId" TEXT NOT NULL, "type" TEXT NOT NULL, "url" TEXT, "screenshotPath" TEXT, "extractedData" JSONB, "description" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Evidence_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Approval" ("id" TEXT NOT NULL, "missionId" TEXT NOT NULL, "stepId" TEXT NOT NULL, "action" TEXT NOT NULL, "riskLevel" "RiskLevel" NOT NULL, "status" "ApprovalStatus" NOT NULL DEFAULT 'PENDING', "approvedAt" TIMESTAMP(3), "rejectedAt" TIMESTAMP(3), CONSTRAINT "Approval_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExecutionEvent" ("id" TEXT NOT NULL, "missionId" TEXT NOT NULL, "stepId" TEXT, "eventType" TEXT NOT NULL, "message" TEXT NOT NULL, "metadata" JSONB, "timestamp" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ExecutionEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AgentStep_missionId_order_key" ON "AgentStep"("missionId", "order");
CREATE INDEX "Mission_userId_createdAt_idx" ON "Mission"("userId", "createdAt");
CREATE INDEX "AgentStep_missionId_status_idx" ON "AgentStep"("missionId", "status");
CREATE INDEX "Approval_missionId_status_idx" ON "Approval"("missionId", "status");
CREATE INDEX "ExecutionEvent_missionId_timestamp_idx" ON "ExecutionEvent"("missionId", "timestamp");
ALTER TABLE "AgentStep" ADD CONSTRAINT "AgentStep_missionId_fkey" FOREIGN KEY ("missionId") REFERENCES "Mission"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Evidence" ADD CONSTRAINT "Evidence_stepId_fkey" FOREIGN KEY ("stepId") REFERENCES "AgentStep"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Approval" ADD CONSTRAINT "Approval_missionId_fkey" FOREIGN KEY ("missionId") REFERENCES "Mission"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Approval" ADD CONSTRAINT "Approval_stepId_fkey" FOREIGN KEY ("stepId") REFERENCES "AgentStep"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ExecutionEvent" ADD CONSTRAINT "ExecutionEvent_missionId_fkey" FOREIGN KEY ("missionId") REFERENCES "Mission"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ExecutionEvent" ADD CONSTRAINT "ExecutionEvent_stepId_fkey" FOREIGN KEY ("stepId") REFERENCES "AgentStep"("id") ON DELETE SET NULL ON UPDATE CASCADE;
